// Purpose: ROW-129 (REQ-011, REQ-012, REQ-031) — after Replace or Ignore on a word deep in a long
// offer, the view does not jump, and focus stays at the word or moves to the next highlighted word.
// Provenance: generated by tests/invariants/spanish-dictionary.ts (accentPopulation, dictionary-es
// 4.0.0 pinned by SHA-256) with a fresh seed per run; positions are the test's own record.
//
// Test argument
// ROW-129 promise: after Replace or Ignore on a word deep in a long offer the view does not jump, and
//   focus stays at the word or moves to the next highlighted word (origin: domain; REQ-011, REQ-012,
//   REQ-031 keyboard use).
// ROW-129 wrong product: a page that redraws the box after each choice, resetting its scroll to the
//   top and dropping the focus on the body — the writer loses their place 60 lines down.
// ROW-129 given: a 70-line offer with fresh misspellings on lines 45, 52 and 60 (all of the same
//   length when corrected, so nothing reflows), checked; the word on line 45 brought into view and
//   opened; when: its intended correction is chosen; then the word on line 52 is opened and Ignore is
//   chosen; then: after each, the next highlight's position on screen moved by at most 4 px, and the
//   focus is in the box with the caret within the word just handled, or on the next highlight (line
//   52, then line 60) — and before each choice that position was measured on the same element.
// ROW-129 controls: the three deep words are highlighted and the first opens a menu offering its
//   correction — the deep case is reached; untouched by a scroll or focus fault.
// ROW-129 technique: positions measured on the screen (whatever scrolls — page or box), the focus read
//   from the page's own focused element and caret.
// cases: ROW-129 target=ROW-129-after-replace-or-ignore-deep-in-a-long-offer-the-view-holds-and-focus-stays-near control=ROW-129-control-the-deep-words-are-highlighted-and-offer-their-correction

import { expect, test, type Page } from '@playwright/test';
import { accentPopulation, asActor, enterOffer, freshRandom, openChecker, pressCheck, readHighlights, type Placed, type Rng } from './harness';
import { chooseIgnore, chooseSuggestion, flagLocator, flagsAt, openMenuByPointer, readMenu, readOfferText, replacedAt, settle } from './suggestions-helpers';

const WAIT_MS = 15_000;

function longOffer(rng: Rng) {
  const pop = accentPopulation();
  const picked: { word: string; stripped: string }[] = [];
  while (picked.length < 3) {
    const p = rng.pick(pop);
    if (!picked.some((q) => q.word === p.word || q.stripped.includes(p.stripped) || p.stripped.includes(q.stripped))) picked.push(p);
  }
  const lines: string[] = [];
  for (let i = 0; i < 70; i++) lines.push(`Línea ${i + 1}: buscamos persona para el equipo de trabajo`);
  lines[44] = `buscamos ${picked[0].stripped} para el equipo`;
  lines[51] = `ofrecemos ${picked[1].stripped} con horario flexible`;
  lines[59] = `valoramos ${picked[2].stripped} en proyectos`;
  const text = lines.join('\n');
  const at = (w: string): Placed => {
    const start = text.indexOf(` ${w} `) + 1;
    return { start, end: start + w.length, word: w };
  };
  return { text, picked, places: picked.map((p) => at(p.stripped)) };
}

async function screenTop(page: Page, text: string, start: number): Promise<number> {
  const b = await (await flagLocator(page, text, start, 'ROW-129')).boundingBox();
  if (!b) throw new Error(`ROW-129: the highlight at offset ${start} has no box on screen`);
  return b.y;
}

/** Where the focus is: a caret offset in the box, or the offset of the focused highlight. */
async function focusAt(page: Page, text: string): Promise<{ caret: number | null; flag: number | null }> {
  const flag = (await flagsAt(page, text)).find((f) => f.active)?.start ?? null;
  const caret = await page.evaluate(() => {
    const box = document.querySelector('[data-element="offer"]');
    const a = document.activeElement;
    if (!box || !a || !(a === box || box.contains(a))) return null;
    if (a instanceof HTMLTextAreaElement || a instanceof HTMLInputElement) return a.selectionStart;
    const sel = window.getSelection();
    if (!sel || !sel.focusNode || !box.contains(sel.focusNode)) return null;
    const r = document.createRange();
    r.setStart(box, 0);
    r.setEnd(sel.focusNode, sel.focusOffset);
    return r.toString().length;
  });
  return { caret, flag };
}

test('ROW-129-after-replace-or-ignore-deep-in-a-long-offer-the-view-holds-and-focus-stays-near', async ({ page }) => {
  asActor('anonymous');
  const rng = freshRandom();
  const { text, picked, places } = longOffer(rng);
  const [p45, p52, p60] = places;
  await openChecker(page);
  await enterOffer(page, text);
  expect((await pressCheck(page)).status, 'ROW-129: the check is answered').toBe(200);
  await expect
    .poll(async () => (await readHighlights(page, text)).map((h) => `${h.word}@${h.start}`), { message: `ROW-129: the three deep misspellings are highlighted (seed ${rng.seed})`, timeout: WAIT_MS })
    .toEqual(places.map((p) => `${p.word}@${p.start}`));

  // Replace on line 45
  await openMenuByPointer(page, text, p45.start, 'ROW-129');
  const label = (await readMenu(page)).suggestions.find((s) => s === picked[0].word);
  expect(label, `ROW-129: the menu of "${p45.word}" offers "${picked[0].word}"`).toBeTruthy();
  const before52 = await screenTop(page, text, p52.start);
  await chooseSuggestion(page, label!, 'ROW-129');
  const replaced = replacedAt(text, p45, label!);
  await expect.poll(() => readOfferText(page), { message: 'ROW-129: the Replace is in the box', timeout: WAIT_MS }).toBe(replaced);
  await settle(page);
  const after52 = await screenTop(page, replaced, p52.start);
  expect(Math.abs(after52 - before52), `ROW-129: after Replace the view does not jump — the next highlight moved ${after52 - before52} px`).toBeLessThanOrEqual(4);
  const f1 = await focusAt(page, replaced);
  expect(
    (f1.caret !== null && f1.caret >= p45.start && f1.caret <= p45.start + label!.length) || f1.flag === p52.start,
    `ROW-129: after Replace the focus stays at the word (caret in ${p45.start}..${p45.start + label!.length}) or moves to the next highlight (${p52.start}) — got ${JSON.stringify(f1)}`,
  ).toBe(true);

  // Ignore on line 52
  await openMenuByPointer(page, replaced, p52.start, 'ROW-129');
  const before60 = await screenTop(page, replaced, p60.start);
  await chooseIgnore(page, 'ROW-129');
  await expect.poll(async () => (await flagsAt(page, replaced)).map((f) => f.start), { message: 'ROW-129: Ignore clears the highlight', timeout: WAIT_MS }).not.toContain(p52.start);
  await settle(page);
  const after60 = await screenTop(page, replaced, p60.start);
  expect(Math.abs(after60 - before60), `ROW-129: after Ignore the view does not jump — the next highlight moved ${after60 - before60} px`).toBeLessThanOrEqual(4);
  const f2 = await focusAt(page, replaced);
  expect(
    (f2.caret !== null && f2.caret >= p52.start && f2.caret <= p52.end) || f2.flag === p60.start,
    `ROW-129: after Ignore the focus stays at the word (caret in ${p52.start}..${p52.end}) or moves to the next highlight (${p60.start}) — got ${JSON.stringify(f2)}`,
  ).toBe(true);
});

test('ROW-129-control-the-deep-words-are-highlighted-and-offer-their-correction', async ({ page }) => {
  asActor('anonymous');
  const rng = freshRandom();
  const { text, picked, places } = longOffer(rng);
  await openChecker(page);
  await enterOffer(page, text);
  expect((await pressCheck(page)).status, 'ROW-129 control: the check is answered').toBe(200);
  await expect
    .poll(async () => (await readHighlights(page, text)).map((h) => `${h.word}@${h.start}`), { message: 'ROW-129 control: the deep misspellings are highlighted', timeout: WAIT_MS })
    .toEqual(places.map((p) => `${p.word}@${p.start}`));
  await openMenuByPointer(page, text, places[0].start, 'ROW-129 control');
  expect((await readMenu(page)).suggestions.map((s) => s.toLowerCase()), 'ROW-129 control: the deep word offers its correction').toContain(picked[0].word);
});
